import { useFavorites } from 'context/FavoritesContext';
import { Container, Title, WatchButton } from "./MovieCard.styled";

export default function MovieCard({ movie, isDark = false }) {
  const { toggleFavorite, isFavorite } = useFavorites();
  // Робимо безпечну деструктуризацію
  const { 
    poster_path, 
    title, 
    release_date, 
    vote_average, 
    overview, 
    genres 
  } = movie || {};

  const liked = isFavorite(movie?.id); // чи вже лайкнуто

  // Картинка-заглушка, якщо у фільму немає постера
  const defaultImg = 'https://dl-media.viber.com/pg_viewer/detail/pd-4/media/0970/5222/2191/3365/8221/3041/8221304192770219.jpg';

  // Збільшуємо якість постера 
  const url = poster_path ? `https://image.tmdb.org/t/p/w185${poster_path}` : defaultImg;
  
  // Безпечно мапимо жанри
  const movieGenres = genres ? genres.map(genre => genre.name) : [];

  // Автоматичний лінк на пошук трейлера фільму на YouTube
  const youtubeSearchUrl = `https://www.youtube.com/results?search_query=${encodeURIComponent((title || "") + " official trailer")}`;

  // ← кольори залежно від теми
  const textColor = isDark ? '#e0e0e0' : '#444';
  const headingColor = isDark ? '#ffffff' : '#111';
  const subHeadingColor = isDark ? '#b0c4de' : '#555';

  return (
    <Container>
      <div style={{ position: 'relative' }}>
      <img src={url} alt={title || "Movie poster"} />
      {/* Кнопка лайку поверх постера */}
        <button
          onClick={() => toggleFavorite(movie)}
          style={{
            position: 'absolute',
            top: '8px',
            right: '8px',
            background: 'rgba(0,0,0,0.5)',
            border: 'none',
            borderRadius: '50%',
            width: '36px',
            height: '36px',
            fontSize: '18px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          {liked ? '❤️' : '🤍'}
        </button>
      </div>
      
      <div>
        {/* Назва та рік в один рядок із правильними шрифтами */}
        <Title>
          {title || "Unknown Title"} 
          <span style={{ fontWeight: 500, color: subHeadingColor, marginLeft: '8px' }}>
            ({release_date?.slice(0, 4) || "????"})
          </span>
        </Title>
        
        <p style={{ color: textColor }}>
          <strong style={{ color: headingColor }}>User score:</strong> {Math.round(vote_average * 10)}%
        </p> 
        
        <h4 style={{ color: headingColor }}>Overview</h4>
        <p style={{ color: textColor }}>{overview || "No overview available."}</p>        
        
        <h4 style={{ color: headingColor }}>Genres</h4> {/* жанри */}
        <p style={{ color: textColor }}>{movieGenres.length > 0 ? movieGenres.join(', ') : "No genres"}</p>
           
        {/* кнопка перегляду фільмів */}
        <WatchButton href={youtubeSearchUrl} target="_blank" rel="noopener noreferrer">
          Watch Trailer
        </WatchButton>
      </div>
    </Container>
  );
}